115:  if(!confirm(`Rebirth this age for ${gained} Divine ${gained===1?'Spark':'Sparks'}? Essence and all upgrades will reset; sparks are permanent.`))return;
116:  state.sparks+=gained;state.essence=0;state.runEarned=0;state.levels=upgrades.map(()=>0);state.lastSaved=Date.now();saveGame();render();$('shopList').scrollTop=0;showToast(`A new age dawns · +${gained} Divine ${gained===1?'Spark':'Sparks'}`);
117: }
