content.text:
:root{color-scheme:dark;--ink:#f7ecff;--muted:#b7a3d1;--plum:#170e2b;--panel:#24163d;--line:#533875;--violet:#9a62ec;--pink:#ff72d2;--gold:#ffdf91}
*{box-sizing:border-box}
html{min-height:100%;background:var(--plum)}
body{margin:0;min-height:100vh;color:var(--ink);font-family:ui-monospace,SFMono-Regular,Consolas,monospace;background:radial-gradient(ellipse at 42% 18%,#462466 0,#24163d 35%,#170e2b 75%);image-rendering:pixelated}
button{font:inherit;color:inherit}
.app{max-width:1440px;margin:auto;padding:18px clamp(12px,2.4vw,32px) 28px}
.topbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:16px}
.brand{display:flex;align-items:center;gap:12px}
.brand-icon{width:44px;height:44px;display:grid;place-items:center;background:#392254;border:3px solid #8658b8;box-shadow:4px 4px #10091b;font-size:25px}
.brand h1{font-size:clamp(17px,2.4vw,26px);letter-spacing:.07em;margin:0;text-transform:uppercase}
.brand p{margin:4px 0 0;color:var(--muted);font-size:11px;letter-spacing:.12em}
.top-actions{display:flex;gap:8px}
.tiny-btn{background:#291a41;border:2px solid #634387;padding:9px 12px;cursor:pointer;box-shadow:3px 3px #10091b}
.tiny-btn:hover{background:#40245b}
.stats{display:grid;grid-template-columns:1.35fr 1fr 1fr 1.12fr;gap:10px;margin-bottom:14px}
