.stat:first-child .stat-value{color:#f4cfff}
.stat-sub{display:block;color:#b29acb;font-size:10px;margin-top:3px}
.game-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(330px,.8fr);gap:14px;align-items:stretch}
