.scene-panel{position:relative;display:flex;flex-direction:column;overflow:hidden;min-height:610px}
.scene-head{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:14px 16px 0}
.eyebrow{font-size:10px;color:#c5a6e2;letter-spacing:.16em;text-transform:uppercase}
.build-count{color:#f2ca8e;font-size:11px}
.sky{position:absolute;inset:52px 0 70px;background:radial-gradient(ellipse at 51% 58%,#b064ff33,transparent 48%),linear-gradient(180deg,#211333,#281743 65%,#211333)}
.stars{position:absolute;inset:0;opacity:.65;background-image:radial-gradient(#ffe8ff 1px,transparent 1.5px),radial-gradient(#bd8aff 1px,transparent 1.5px);background-size:61px 53px,89px 77px;background-position:13px 10px,27px 22px}
.moon{position:absolute;top:8%;right:19%;height:42px;width:42px;background:#d6a8ff;box-shadow:8px 0 #281743,0 0 22px #bc7dff;opacity:.8}
.scene-click{position:relative;z-index:1;display:grid;place-items:center;flex:1;min-height:0;padding:4px 5px 0;border:0;background:transparent;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}
.scene-click:focus-visible{outline:3px dashed var(--pink);outline-offset:-8px}
.temple-svg{width:min(100%,720px);height:auto;max-height:490px;overflow:visible;image-rendering:pixelated;filter:drop-shadow(0 11px #05020c3d);transition:transform .08s}
.scene-click:active .temple-svg{transform:translateY(4px) scale(.99)}
.floor-glow{position:absolute;bottom:15%;left:18%;right:18%;height:34px;background:#a640f1;filter:blur(20px);opacity:.28;pointer-events:none}
.click-hint{position:absolute;z-index:3;bottom:19px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#e3c9f8;font-size:11px;letter-spacing:.08em;text-shadow:2px 2px #1a0c29}
.float-text{position:absolute;z-index:5;pointer-events:none;font-weight:bold;color:#ffddff;text-shadow:2px 2px #6f31a9;animation:floatup .8s ease-out forwards}
@keyframes floatup{to{transform:translateY(-42px);opacity:0}
.shop-panel{display:flex;flex-direction:column;max-height:720px}
.shop-head{padding:14px 15px 10px;border-bottom:2px solid #49315f;background:#291a40}
.shop-title{display:flex;justify-content:space-between;align-items:baseline}
.shop-title h2{font-size:15px;letter-spacing:.13em;text-transform:uppercase;margin:0}
.shop-title span{font-size:10px;color:#bca2d4}
.shop-note{font-size:10px;color:#bda8d0;margin:6px 0 0}
.shop-list{overflow-y:auto;overscroll-behavior:contain;padding:7px;scrollbar-color:#77509a #201431;scrollbar-width:thin}
.upgrade{position:relative;display:grid;grid-template-columns:38px minmax(0,1fr) auto;gap:9px;align-items:center;width:100%;text-align:left;padding:9px;margin:4px 0;background:#2c1d43;border:2px solid #49315e;box-shadow:2px 2px #160d24;cursor:pointer;transition:background .12s,border-color .12s;touch-action:manipulation}
.upgrade:hover:not(:disabled){background:#39244f;border-color:#9464b4}
.upgrade:disabled{opacity:.54;cursor:not-allowed}
.upgrade.affordable{border-color:#a077c4}
.upgrade-icon{width:34px;height:34px;display:grid;place-items:center;background:#3a2753;border:2px solid #5a4077;font-size:17px}
.upgrade-name{font-weight:bold;font-size:12px;display:block;color:#f5e9ff}
.upgrade-desc{display:block;color:#baa6cc;font-size:10px;line-height:1.4;margin-top:3px}
.upgrade-cost{color:#f5d69c;font-weight:bold;font-size:11px;text-align:right;white-space:nowrap}
.upgrade-level{display:block;color:#bda5d5;font-size:9px;margin-top:4px}
.prestige-card{margin:10px 7px 8px;padding:12px;background:linear-gradient(135deg,#3b2454,#2b1a40);border:2px solid #8154a0;box-shadow:3px 3px #130a1c}
.prestige-row{display:flex;justify-content:space-between;gap:8px;align-items:center}
.prestige-card h3{margin:0;font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:#f4d0ff}
.spark-total{font-size:11px;color:#ffe8a6}
.prestige-card p{font-size:10px;color:#cbb6dc;line-height:1.5;margin:7px 0}
.prestige-btn{width:100%;border:2px solid #c06de4;background:#673b85;padding:9px;cursor:pointer;font-size:11px;font-weight:bold;box-shadow:3px 3px #1a0e29}
.prestige-btn:disabled{filter:grayscale(.7);opacity:.55;cursor:not-allowed}
.prestige-btn:not(:disabled):hover{background:#8c4db0}
.footer{display:flex;justify-content:space-between;gap:12px;padding:10px 14px;color:#9e87b6;font-size:9px;border-top:1px solid #3d2b52}
.toast{position:fixed;z-index:20;top:18px;left:50%;transform:translate(-50%,-20px);opacity:0;pointer-events:none;background:#482b62;border:2px solid #b477db;padding:10px 14px;box-shadow:4px 4px #130a1c;font-size:12px;transition:.2s}
.toast.show{opacity:1;transform:translate(-50%,0)}
