72: // Save a compact JSON state so it remains portable and easy to reset.
73: const SAVE_KEY='violet-veil-save-v1', PRESTIGE_THRESHOLD=1_000_000, OFFLINE_CAP=8*60*60*1000;
74: const initialState=()=>({essence:0,runEarned:0,totalEarned:0,sparks:0,levels:upgrades.map(()=>0),lastSaved:Date.now(),sound:false});
75: let state=initialState(),saveTimer=0,toastTimer=0,audioContext=null;
76: const $=id=>document.getElementById(id);
77: const numberFormat=value=>{
78:  if(!Number.isFinite(value))return '∞';
79:  const abs=Math.abs(value);
80:  if(abs<1000)return (abs%1===0?String(abs):abs.toFixed(abs<10?1:0)).replace(/\.0$/,'');
81:  const units=['K','M','B','T','Qa','Qi','Sx','Sp','Oc','No','Dc'];
82:  const tier=Math.floor(Math.log10(abs)/3);
83:  if(tier>units.length)return value.toExponential(2);
84:  const scaled=abs/Math.pow(1000,tier);
85:  return `${value<0?'-':''}${scaled.toFixed(scaled<10?1:0).replace(/\.0$/,'')}${units[tier-1]}`;
86: };
87: const multiplier=()=>1+state.sparks*.05;
88: const clickPower=()=>multiplier()*(1+upgrades.reduce((sum,u,i)=>sum+(u.kind==='click'?u.power*state.levels[i]:0),0));
89: const essencePerSecond=()=>multiplier()*upgrades.reduce((sum,u,i)=>sum+(u.kind==='eps'?u.power*state.levels[i]:0),0);
90: const upgradeCost=i=>Math.ceil(upgrades[i].base*Math.pow(1.2,state.levels[i]));
91: function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
92: function saveGame(){
93:  state.lastSaved=Date.now();
94:  try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('saveStatus').textContent='All progress saved'}
95:  catch(error){$('saveStatus').textContent='Save unavailable';console.warn('Could not save game:',error)}
96: }
97: function loadGame(){
98:  try{
99:   const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');
100:   if(!saved||!Array.isArray(saved.levels))return;
101:   state={...initialState(),...saved};
102:   state.levels=upgrades.map((_,i)=>Math.max(0,Math.floor(Number(saved.levels[i])||0)));
103:   for(const key of ['essence','runEarned','totalEarned','sparks'])state[key]=Math.max(0,Number(saved[key])||0);
